const realMediaCopy=window.MDFlagship?.copy||{};
const retiredGalleryPhotos={0:{src:'md-community-v24.webp',key:'communityCaption'},2:{src:'md-culture-v24.webp',key:'cultureCaption'},3:{src:'md-consultation-v24.webp',key:'consultationCaption'},4:{src:'md-team-v24.webp',key:'teamCaption'}};
