function migrateRealMedia(data){
  const h=data.home;
  if(data.illustrationRevision!==26){
    if(h){
      if(!h.heroImg||['md-team-v24.webp','assets/md-team-v24.webp'].includes(h.heroImg))h.heroImg=defaultHome.heroImg;
      for(const [index,media] of Object.entries(retiredGalleryPhotos)){
        const item=h.gallery?.[index],original=defaultHome.gallery[index];
        if(item&&[media.src,'assets/'+media.src].includes(item.src)){
          item.src=original.src;
          if(item.caption===realMediaCopy[media.key]?.[0])item.caption=original.caption;
        }
      }
    }
    data.illustrationRevision=26;
  }
  if(data.videoIllustrationRevision===27)return;
  const retiredFilms=['assets/md-field-film-v24.mp4','md-field-film-v24.mp4'];
  const retiredPosters=['md-film-poster-v24.webp','assets/md-film-poster-v24.webp'];
  const silentBodies=['Phim ngắn không lời ghi lại khu vực nhà ăn và không gian bên ngoài trong một chuyến thăm nhà máy.','A short silent film showing the cafeteria and outdoor areas during a factory visit.','无声短片记录一次工厂走访中的食堂与室外区域。','공장 방문 중 식당과 외부 공간을 담은 짧은 무음 영상입니다.'];
  const restore=(record,kind,id,original,fields)=>{
    if(!record)return;
    const videoKey=kind==='home'?'videoUrl':'video',posterKey=kind==='home'?'videoPoster':'cover';
    if(retiredFilms.includes(record[videoKey])){
      record[videoKey]='';
      for(const [field,key] of Object.entries(fields)){
        if(original&&record[field]!==undefined&&(record[field]===realMediaCopy[key]?.[0]||(field==='body'&&record[field]===silentBodies[0])))record[field]=original[field];
        for(const [index,lang] of ['vi','en','zh','ko'].entries()){
          const translation=data.i18n?.[kind+':'+id]?.[lang];
          if(!translation||!(translation[field]===realMediaCopy[key]?.[index]||(field==='body'&&translation[field]===silentBodies[index])))continue;
          const previous=lang==='vi'?original?.[field]:window.MDTranslate?.content?.(lang,kind,id,field);
          if(previous!==undefined&&previous!=='')translation[field]=previous;
        }
      }
    }
    if(retiredPosters.includes(record[posterKey]))record[posterKey]='video-poster.webp';
  };
  restore(h,'home','main',defaultHome,{videoTitle:'fieldFilmTitle',videoIntro:'fieldFilmIntro'});
  for(const post of data.posts||[])restore(post,'post',post.id,defaultPosts.find(item=>item.id===post.id),{title:'fieldFilmTitle',excerpt:'fieldFilmIntro',body:'fieldFilmBody',seoTitle:'fieldFilmTitle',meta:'fieldFilmIntro'});
  data.videoIllustrationRevision=27;
}
function migrateEditorialData(data,{seedMissing=true}={}){
  migrateRealMedia(data);
  window.MDCompanyProfile?.migrate(data,defaultPartners,{seedMissing});
  if((data.jobImageryRevision||0)<25){
    const qc=(data.jobs||[]).find(job=>job.id==='qc');if(qc?.image==='gallery-line.webp')qc.image='gallery-operator.webp';
    const mechanical=(data.jobs||[]).find(job=>job.id==='cn-co-khi');if(mechanical?.image==='gallery-operator.webp')mechanical.image='mechanical-assembly-v23.webp';
    data.jobImageryRevision=25;
  }
  data.i18n ||= {};data.mediaTransforms ||= {};
  const legacyRequirements={
    en:'College/university education in electrical or mechanical engineering.\n1–3 years of relevant experience preferred.\nAbility to read technical drawings.\nResponsible with strong problem-solving skills.',
    zh:'机电相关专业大专或以上学历。\n优先考虑1–3年相关经验。\n能够阅读技术图纸。\n责任心强，具备解决问题能力。',
    ko:'전기·기계 관련 전문대/대학 졸업.\n관련 경력 1~3년 우대.\n기술 도면 이해 가능.\n책임감과 문제 해결 능력 보유.'
  };
  for(const [lang,legacy] of Object.entries(legacyRequirements)){
    const translation=data.i18n['job:ky-su-co-dien']?.[lang];
    if(translation?.requirements===legacy){translation.requirements=window.MDTranslate.content(lang,'job','ky-su-co-dien','requirements');translation.status='needs-review';translation.reviewFields=[...new Set([...(translation.reviewFields||[]),'requirements'])];}
  }
  if(data.homeCopyRevision!==23){for(const field of Object.keys(homeCopyKeys))if(data.home?.[field]===legacyHomeCopy[field])data.home[field]=defaultHome[field];data.homeCopyRevision=23;}
  if(data.editorialRevision===21)return data;
  for(const post of data.posts||[]){
    const old=legacyEditorialPosts.find(p=>p.id===post.id),fresh=defaultPosts.find(p=>p.id===post.id);
    if(!old||!fresh)continue;
    for(const field of ['title','excerpt','body'])if(post[field]===old[field])post[field]=fresh[field];
  }
  data.editorialRevision=21;return data;
}
const defaults=()=>({companyDemoRevision:1,realMediaRevision:24,illustrationRevision:26,videoIllustrationRevision:27,social:{enabled:true,hotline:'0364562868',zalo:'https://zalo.me/0329138082',messenger:''},jobs:structuredClone(defaultJobs),posts:structuredClone(defaultPosts),home:structuredClone(defaultHome),partners:structuredClone(defaultPartners),mediaTransforms:{},audit:[],i18n:{},...window.MDCompanyProfile?.seed()});
