(db.posts||[]).forEach(p=>{p.cover=upgradeV10Image(p.cover)});
(db.posts||[]).forEach(p=>{if(v14Covers[p.id]&&['gallery-line.webp','gallery-meeting.webp'].includes(p.cover))p.cover=v14Covers[p.id];});

