function editorialMeta(post){if(!post||!window.MDEditorial||post.type!=='article')return null;const content=window.MDEditorial.articleRecord(post.id,currentLang);return content&&localize('post',post.id,'body',post.body)===content.body?window.MDEditorial.articleMeta(post.id,currentLang):null;}
function sampleTranslation(lang,kind,id,field){if(kind==='home'&&homeCopyKeys[field]){const value=window.MDFlagship?.copy?.[homeCopyKeys[field]]?.[{vi:0,en:1,zh:2,ko:3}[lang]];if(value)return value;}if(kind==='post'){const content=window.MDEditorial?.articleRecord(id,lang);if(content&&field in content)return content[field];}return window.MDTranslate?.content?.(lang,kind,id,field)||'';}
const localize=(kind,id,field,base)=>{const bundle=db.i18n?.[kind+':'+id],seed=kind==='home'?defaultHome:kind==='job'?defaultJobs.find(j=>j.id===id):defaultPosts.find(p=>p.id===id);return bundle?.[currentLang]?.[field]||(base===seed?.[field]&&sampleTranslation(currentLang,kind,id,field))||base};
const jobHref=j=>'chi-tiet-viec-lam.html?id='+encodeURIComponent(j.id)+('&lang='+currentLang)+(page==='jobs'?'&from='+encodeURIComponent(jobReturnContext(j)):'');const articleHref=p=>window.MDLocale.newsHref(page==='news'||page==='article'?{kind:newsKind,query:newsQuery}:{},currentLang,p.id);
const imgSrc=src=>{const value=String(src||'gallery-line.webp').trim();if(/^data:image\/(?:png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(value))return value;if(/^[\w-]+\.(?:png|jpe?g|webp|svg)$/i.test(value))return A+value;if(value.startsWith('assets/')&&/^assets\/[\w./-]+$/.test(value)&&!value.includes('..'))return value;if(value.startsWith('https://')){try{const u=new URL(value);if(!u.username&&!u.password)return u.href.replace(/[<>"']/g,c=>'%'+c.charCodeAt(0).toString(16));}catch{}}return A+'gallery-line.webp';};
