function sectionHead(kicker,title,href,label){return `<div class="section-head"><div><div class="eyebrow">${kicker}</div><h2>${title}</h2></div>${href?`<a class="btn light sm" href="${href}">${label||'Xem tất cả'} ${I('arrow','sm')}</a>`:''}</div>`}
function crumb(label){return `<nav class="crumb" aria-label="Breadcrumb"><ol><li><a href="index.html">Trang chủ</a></li><li class="crumb-separator" aria-hidden="true">›</li><li aria-current="page">${E(label)}</li></ol></nav>`}
function subhero(title,description){return `<section class="hero hero-sub"><div class="container hero-grid"><div class="hero-content">${crumb(title)}<h1>${E(title)}</h1><p>${E(description)}</p></div><div class="hero-image" role="img" aria-label="Hình minh họa nhân sự trong nhà máy"></div></div></section>`}
function urgency(j){return j.urgent?`<span class="pill urgent">● ${C('urgent')}</span>`:`<span class="pill">${C('hiring')}</span>`}
function tags(j,max=4){return `<div class="tag-row">${(j.tags||[]).slice(0,max).map(x=>`<span class="pill">${E(x)}</span>`).join('')}</div>`}
function mediaCaption(media){
  return media.caption||'';
}
function galleryHTML(limit){return `<div class="gallery-grid">${db.home.gallery.slice(0,limit||db.home.gallery.length).map((im,i)=>`<a class="gallery-item" href="#" aria-label="Xem ảnh hoạt động" data-image="${E(imgSrc(im.src))}" data-caption="${E(mediaCaption(im))}"><img src="${E(imgSrc(im.src))}" alt="${E(mediaCaption(im))}" loading="lazy"><span>${E(mediaCaption(im))}</span></a>`).join('')}</div>`}
function videoBlock(url,poster,mediaKey='video'){
 const label=window.MDExperience.videoLabel(url,currentLang),image=`<img data-media-key="${E(mediaKey)}" src="${E(imgSrc(poster||'video-poster.webp'))}" alt="${E(label.poster)}" loading="lazy">`;
 if(!String(url||'').trim())return `<figure class="video-poster md-video-unavailable">${image}<figcaption><strong>${E(label.empty)}</strong><span>${E(label.description)}</span></figcaption></figure>`;
 return `<a class="video-poster" href="#" data-video="${E(url)}" aria-label="${E(label.play)}">${image}<span class="play">${I('video','xl')}</span><span class="duration">VIDEO</span></a>`;
}

