const introAdmin=(title,sub,buttons='')=>`<div class="admin-heading"><div><div class="eyebrow">MINH ĐỨC / CONTENT STUDIO</div><h1>${title}</h1><div class="muted">${sub}</div></div><div class="admin-actions">${buttons}</div></div>`;
function homeAdmin(){const h=db.home;const section=(id,code,title,desc,inside,open=false)=>`<details class="cms-section" ${open?'open':''}><summary><span class="cms-section-no">${code}</span><span><b>${title}</b><small>${desc}</small></span><span class="cms-chevron">⌄</span></summary><div class="cms-section-content">${inside}</div></details>`;const input=(name,label,large=false)=>`<div class="field"><label>${label}</label>${large?`<textarea name="${name}" rows="4">${E(h[name]||'')}</textarea>`:`<input name="${name}" value="${E(h[name]||'')}">`}</div>`;const toggles=[['stats','Nguyên tắc thông tin'],['about','Giới thiệu & dịch vụ'],['gallery','Thư viện ảnh'],['video','Video giới thiệu'],['jobs','Việc làm nổi bật'],['partners','Doanh nghiệp đối tác'],['news','Tin tức'],['cta','Liên hệ']];return introAdmin('Biên tập trang chủ','Từng khu vực là một module độc lập. Mở mục cần chỉnh, lưu toàn bộ để tránh thay đổi bố cục.',`<a href="index.html" class="btn light" target="_blank">${I('eye','sm')} Xem trang chủ</a><button form="homeEditForm" class="btn red">${I('save','sm')} Lưu trang chủ</button>`)+`<div class="cms-toolbar"><span class="pill success">8 module bố cục đã khóa</span><span class="small">Thay ảnh và bản dịch ở ngay mỗi phần</span></div><form id="homeEditForm" class="cms-editor-form"><div class="cms-sections">${section('hero','01','Hero & Banner','Thông điệp, ảnh chủ đạo, CTA',`<div class="form-grid">${input('heroLine1','Dòng tiêu đề 1')}${input('heroLine2','Dòng tiêu đề 2')}${input('heroIntro','Mô tả Hero',true)}</div>${contextMedia('hero','Ảnh Hero / Banner chính')}`,true)}${section('about','02','Giới thiệu doanh nghiệp','Thông điệp thương hiệu và mô tả',`<div class="form-grid">${input('aboutTitle','Tiêu đề giới thiệu')}${input('aboutIntro','Nội dung giới thiệu',true)}</div>`)}${section('kpi','03','Nguyên tắc thông tin','Nội dung ổn định thay cho số liệu chưa xác minh',`<div class="notice">Khối 3 nguyên tắc: Rõ công việc · Rõ thu nhập · Dễ kết nối. Bật/tắt tại mục 06. Các chỉ số doanh nghiệp cũ vẫn được giữ trong dữ liệu, chưa công bố khi chưa được xác minh.</div>`)}${section('gallery','04','Hình ảnh hoạt động','Từng ảnh + chú thích + căn ảnh',`${input('galleryTitle','Tiêu đề album')}<div class="cms-gallery-grid">${h.gallery.map((im,i)=>`<div class="cms-photo-card">${contextMedia('gallery'+i,'Ảnh '+(i+1),true)}<div class="field"><label>Chú thích ảnh ${i+1}</label><input name="galleryCaption${i}" value="${E(im.caption)}"></div></div>`).join('')}</div>`)}${section('video','05','Video giới thiệu','Poster, video và lời giới thiệu',`<div class="form-grid">${input('videoTitle','Tiêu đề video')}${input('videoIntro','Giới thiệu video',true)}</div>${window.MDExperience.editorHtml('home',h.videoUrl||'','videoUrl')}${contextMedia('video','Ảnh poster video')}`)}${section('visibility','06','Ẩn / hiện các khối','Không kéo thả; các section tự nối liền mạch',`${toggles.map(([k,t])=>`<label class="section-setting"><span><b>${t}</b><small>Khối độc lập / layout cố định</small></span><input type="checkbox" name="section_${k}" ${h.sections[k]?'checked':''}></label>`).join('')}`)}${section('languages','07','Ngôn ngữ của trang chủ','Hiệu đính EN / ZH / KO ngay tại đây',inlineTranslationPanel('home','main',['heroLine1','heroLine2','heroIntro','aboutTitle','aboutIntro','galleryTitle','videoTitle','videoIntro'],h))}</div><div class="cms-form-footer"><span>${I('shield','sm')} Nội dung tiếng Việt là nguồn; dịch thiếu hoặc lỗi sẽ dùng tiếng Việt.</span><button class="btn red" type="submit">${I('save','sm')} Lưu tất cả thay đổi</button></div></form>`}
function jobsAdmin(){return introAdmin('Quản lý tin tuyển dụng','Tạo, sửa, tạm ẩn các tin tuyển dụng phổ thông và nội bộ.',`<button class="btn red" data-new-job>${I('plus','sm')} Thêm tin tuyển dụng</button>`)+`<div class="admin-card"><div class="row between"><h3 style="margin:0">Danh sách tuyển dụng</h3><span class="pill">${db.jobs.length} tin</span></div><div style="overflow:auto;margin-top:18px"><table class="admin-table"><thead><tr><th>Vị trí / Loại</th><th>Địa điểm</th><th>Thu nhập</th><th>Hiển thị</th><th>Hành động</th></tr></thead><tbody>${db.jobs.map(j=>`<tr><td><b>${E(j.title)}</b><small>${j.type==='internal'?'Tuyển dụng nội bộ · CV bắt buộc':'Lao động phổ thông'}</small></td><td>${E(j.park)} · ${E(j.location)}</td><td>${j.min}–${j.max} triệu</td><td><span class="pill ${j.open?'success':'neutral'}">${j.open?'Đang hiển thị':'Tạm ẩn'}</span></td><td class="actions"><button data-edit-job="${E(j.id)}">${I('edit','sm')} Sửa</button><button data-visibility-job="${E(j.id)}">${j.open?'Ẩn tin':'Hiện tin'}</button><a href="${jobHref(j)}" class="link">Xem ${I('arrow','sm')}</a></td></tr>`).join('')}</tbody></table></div></div>`}
function jobEditor(){const j=db.jobs.find(x=>x.id===editJobId);if(!j)return jobsAdmin();const fields4=[['description','Mô tả công việc','Nhiệm vụ và công việc chính'],['requirements','Yêu cầu ứng viên','Tiêu chí tuyển dụng'],['benefits','Quyền lợi nổi bật','Lương, thưởng, bảo hiểm và hỗ trợ'],['apply','Cách ứng tuyển','Hướng dẫn nộp hồ sơ']];const side=`<div class="stack"><div class="admin-card"><h3>${I('eye','sm')} Trạng thái hiển thị</h3><label class="choice"><input type="radio" name="open" value="true" ${j.open?'checked':''} form="jobEditForm">Đang hiển thị trên website</label><label class="choice"><input type="radio" name="open" value="false" ${!j.open?'checked':''} form="jobEditForm">Tạm ẩn / chưa xuất bản</label></div><div class="admin-card"><h3>Liên kết cố định URL</h3><div class="field"><label>Slug (SEO)</label><input name="slug" form="jobEditForm" value="${E(j.slug||slug(j.title))}"></div><p class="small">chi-tiet-viec-lam.html?id=${E(j.id)}</p></div><div class="admin-card"><h3>${I('globe','sm')} Đa ngôn ngữ</h3>${langStatuses('job',j.id)}<div class="notice" style="margin-top:12px">Bên dưới phần Cách ứng tuyển có khu vực hiệu đính bản dịch trực tiếp. Nếu lỗi dịch, dùng tiếng Việt.</div></div></div>`;
return introAdmin('Sửa tin tuyển dụng',`Đang chỉnh sửa: ${E(j.title)}`,`<button class="btn light" data-admin="jobs">Hủy bỏ</button><a href="${jobHref(j)}" class="btn light">Xem trên website</a><button form="jobEditForm" class="btn red">${I('save','sm')} Lưu thay đổi</button>`)+`<div class="admin-tabs">${[['general','Thông tin chung'],...fields4.map(x=>[x[0],x[1]]),['i18n','Đa ngôn ngữ']].map(([k,t])=>`<a class="sortbtn ${k==='general'?'active':''}" href="#edit-${k}">${t}</a>`).join('')}</div><form id="jobEditForm" class="editor-layout"><div class="stack"><div class="admin-card" id="edit-general"><h3>Thông tin cơ bản</h3><div class="form-grid"><div class="field"><label>Vị trí tuyển dụng *</label><input name="title" required maxlength="255" value="${E(j.title)}"></div><div class="field"><label>Đơn vị tuyển dụng</label><input name="company" value="${E(j.company)}"></div><div class="field"><label>Địa điểm làm việc *</label><input name="location" required maxlength="160" value="${E(j.location||'')}" placeholder="Ví dụ: Bắc Ninh, KCN Yên Phong, hoặc địa chỉ cụ thể" list="locationsHint"><datalist id="locationsHint"><option value="Bắc Ninh"><option value="Bắc Giang"><option value="Hà Nội"><option value="Hải Phòng"></datalist></div><div class="field"><label>Khu công nghiệp</label><input name="park" value="${E(j.park)}"></div><div class="field"><label>Mức lương từ (triệu)</label><input name="min" type="number" min="0" step="0.5" value="${j.min}"></div><div class="field"><label>Đến (triệu)</label><input name="max" type="number" min="0" step="0.5" value="${j.max}"></div><div class="field"><label>Số lượng tuyển</label><input name="openings" type="number" min="1" value="${j.openings||1}"></div><div class="field"><label>Ngày đăng</label><input name="posted" type="date" value="${E(j.posted)}"></div></div><h4 style="margin-bottom:12px">Loại hình tuyển dụng</h4><div class="choice-row"><label class="choice"><input type="radio" name="type" value="worker" ${j.type==='worker'?'checked':''}><span>${I('users')} Lao động phổ thông<small style="display:block">Không cần CV</small></span></label><label class="choice"><input type="radio" name="type" value="internal" ${j.type==='internal'?'checked':''}><span>${I('briefcase')} Tuyển dụng nội bộ<small style="display:block">CV bắt buộc</small></span></label></div><div style="margin:18px 0 12px"><label class="checkbox-line"><input type="checkbox" name="urgent" ${j.urgent?'checked':''}> ${I('briefcase','sm')} Đánh dấu tuyển gấp</label></div>${contextMedia('job:'+j.id,'Ảnh thẻ tuyển dụng')}<div class="field"><label>Đường dẫn ảnh (có thể sửa trực tiếp)</label><input name="image" value="${E(j.image||'gallery-line.webp')}"></div><div class="field" style="margin-top:12px"><label>Tag quyền lợi (cách nhau dấu phẩy)</label><input name="tags" value="${E((j.tags||[]).join(', '))}"></div></div>${fields4.map(([key,title,sub])=>`<details class="cms-section" id="edit-${key}" ${key==='description'?'open':''}><summary><span class="cms-section-no">${fields4.findIndex(x=>x[0]===key)+1}</span><span><b>${title}</b><small>${sub} · Mỗi dòng là một ý</small></span><span class="cms-chevron">⌄</span></summary><div class="cms-section-content"><div class="field"><label>Nội dung tiếng Việt</label><textarea name="${key}" rows="7" required>${E(j[key])}</textarea></div></div></details>`).join('')}<details class="cms-section" id="edit-i18n"><summary><span class="cms-section-no">🌐</span><span><b>Bản dịch EN / ZH / KO</b><small>Hiệu đính nội dung ngay trong tin tuyển dụng</small></span><span class="cms-chevron">⌄</span></summary><div class="cms-section-content">${inlineTranslationPanel('job',j.id,['title','description','requirements','benefits','apply'],j)}</div></details></div>${side}</form>`}
function postsAdmin(){return introAdmin('Bài viết & Tin tức','Quản lý bài viết, tin video và SEO metadata.',`<button class="btn red" data-new-post>${I('plus','sm')} Tạo bài viết</button>`)+`<div class="admin-card"><table class="admin-table"><thead><tr><th>Bài viết</th><th>Định dạng</th><th>SEO title</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody>${db.posts.map(p=>`<tr><td><b>${E(p.title)}</b><small>${E(p.date)}</small></td><td>${p.type==='video'?'Video':'Bài viết'}</td><td>${E(p.seoTitle||'-')}</td><td><span class="pill ${p.visible?'success':'neutral'}">${p.visible?'Hiển thị':'Ẩn'}</span></td><td class="actions"><button data-edit-post="${E(p.id)}">Sửa</button><button data-visibility-post="${E(p.id)}">${p.visible?'Ẩn':'Hiện'}</button><a href="${articleHref(p)}" class="link">Xem</a></td></tr>`).join('')}</tbody></table></div>`+seoAudit()}
function postEditor(){const p=db.posts.find(x=>x.id===editPostId);if(!p)return postsAdmin();return introAdmin('Sửa bài viết / tin video',E(p.title),`<button class="btn light" data-admin="posts">Hủy bỏ</button><a class="btn light" href="${articleHref(p)}">Xem bài viết</a><button form="postEditForm" class="btn red">${I('save','sm')} Lưu nội dung</button>`)+`<form id="postEditForm" class="editor-layout"><div class="stack"><div class="admin-card"><h3>Thông tin bài viết</h3><div class="form-grid"><div class="field"><label>Tiêu đề *</label><input name="title" value="${E(p.title)}" required></div><div class="field"><label>Thể loại</label><select name="type"><option value="article" ${p.type==='article'?'selected':''}>Bài viết</option><option value="video" ${p.type==='video'?'selected':''}>Tin video</option></select></div><div class="field"><label>Chuyên mục</label><input name="category" value="${E(p.category)}"></div><div class="field"><label>Ngày đăng</label><input type="date" name="date" value="${E(p.date)}"></div><div class="field" style="grid-column:span 2"><label>Mô tả ngắn</label><textarea name="excerpt" rows="3">${E(p.excerpt)}</textarea></div><div class="field" style="grid-column:span 2"><label>Nội dung bài viết</label><textarea name="body" rows="9">${E(p.body)}</textarea></div>${contextMedia('post:'+p.id,'Ảnh đại diện bài viết')}<div class="field" style="grid-column:span 2"><label>Đường dẫn ảnh đại diện / poster</label><input name="cover" value="${E(p.cover)}"></div>${window.MDExperience.editorHtml('post:'+p.id,p.video||'','video')}</div></div><div class="admin-card cms-ai-seo"><div class="row between"><h3>${I('spark','sm')} Content Assistant & SEO Studio</h3><span class="pill">Tích hợp</span></div><p class="small">Gợi ý theo quy tắc trong demo. Nội dung phải được biên tập trước khi xuất bản.</p><button type="button" class="btn light" data-inline-seo>${I('spark','sm')} Gợi ý SEO theo tiêu đề bài viết</button><div id="inlineSeoResult" class="small" style="margin:12px 0"></div></div><div class="admin-card"><h3>Chuẩn SEO</h3><div class="field"><label>SEO title</label><input name="seoTitle" value="${E(p.seoTitle||'')}"></div><div class="field" style="margin-top:12px"><label>Meta Description</label><textarea name="meta" rows="3">${E(p.meta||'')}</textarea></div><div class="field" style="margin-top:12px"><label>Từ khóa SEO</label><input name="keyword" value="${E(p.keyword||'')}"></div><p class="small" style="margin-top:12px">Nội dung cần được biên tập và kiểm chứng, không tự xuất bản bài viết AI mà chưa duyệt.</p></div></div><div class="stack"><div class="admin-card"><h3>Đăng bài</h3><label class="checkbox-line"><input type="checkbox" name="visible" ${p.visible?'checked':''}> Hiển thị trên website</label></div><details class="cms-section"><summary><span class="cms-section-no">🌐</span><span><b>Bản dịch bài viết</b><small>Hiệu đính EN / ZH / KO</small></span><span class="cms-chevron">⌄</span></summary><div class="cms-section-content">${inlineTranslationPanel('post',p.id,['title','excerpt','body','seoTitle','meta'],p)}</div></details><div class="admin-card"><h3>Ảnh hiện tại</h3><img src="${imgSrc(p.cover)}" alt="Ảnh đại diện" style="width:100%;border-radius:9px"></div></div></form>`}

function contextMedia(slotId,heading,compact=false){const slot=mediaSlots().find(x=>x.id===slotId);if(!slot)return '';return `<div class="context-media ${compact?'context-media-compact':''}"><div class="context-media-image"><img data-media-key="${E(slot.id)}" src="${E(imgSrc(slot.src))}" alt="${E(heading)}" loading="lazy"></div><div class="context-media-body"><div class="context-media-title">${I('image','sm')} ${E(heading)}</div><p>${E(slot.recommend)} px khuyến nghị · Có bản xem trước desktop/mobile</p><button class="btn light sm" type="button" data-inline-media="${E(slotId)}">${I('image','sm')} Thay ảnh & căn chỉnh <span aria-hidden="true">↗</span></button></div></div>`}
let selectedPartnerId=null, partnerQuery='', partnerVisibility='all';
function partnerMark(p,decorative=false){return window.MDBrandRights?.canDisplayDemo(p)?`<img src="${E(imgSrc(p.logo))}" alt="${decorative?'':E(p.name)}" data-logo-name="${E(p.name)}" width="160" height="64" decoding="async">`:`<span class="partner-mark-text">${E(p.name)}</span>`;}
function partnerState(p){return window.MDBrandRights?.canDisplayDemo(p)?'Logo đang hiển thị trong demo':p.visible?'Hồ sơ đang hiện · Logo đang ẩn':'Đang ẩn trong demo'}
function premiumPartnerAdmin(){const all=db.partners,sel=all.find(x=>x.id===selectedPartnerId)||all[0];if(sel)selectedPartnerId=sel.id;const visible=all.filter(x=>(partnerVisibility==='all'||(partnerVisibility==='visible'?x.visible:!x.visible))&&normalizeSearch([x.name,x.sector,x.country].join(' ')).includes(normalizeSearch(partnerQuery)));return introAdmin('Doanh nghiệp · Demo','Quản lý logo, hồ sơ và thứ tự hiển thị trong bản trình bày với khách hàng.',`<button class="btn light" type="button" data-view-marquee>${I('eye','sm')} Xem dải logo</button><button class="btn red" type="button" data-partner-add>${I('plus','sm')} Thêm doanh nghiệp</button>`)+`<div class="partner-metrics"><div><span>Tổng hồ sơ</span><strong>${all.length}</strong></div><div><span>Hiển thị trên web</span><strong>${all.filter(x=>x.visible).length}</strong></div><div><span>Logo hiển thị trong demo</span><strong>${all.filter(x=>window.MDBrandRights?.canDisplayDemo(x)).length}</strong></div><div><span>Hồ sơ thiếu logo</span><strong>${all.filter(x=>!x.logo).length}</strong></div></div><div class="notice" style="margin:14px 0 20px">${I('shield','sm')} Logo dùng để trình bày giao diện demo. Bật/tắt hiển thị không thay đổi trạng thái xác minh quyền sử dụng.</div><div class="partner-management-grid"><div class="admin-card partner-index"><div class="partner-index-title"><div><h3>Danh sách doanh nghiệp</h3><p class="small">Chọn để xem và chỉnh sửa hồ sơ</p></div><span class="pill">${all.length} hồ sơ</span></div><div class="partner-filters"><input id="partnerSearch" placeholder="Tìm công ty / ngành nghề…" value="${E(partnerQuery)}" aria-label="Tìm doanh nghiệp"><select id="partnerVisibility" aria-label="Trạng thái hiển thị"><option value="all" ${partnerVisibility==='all'?'selected':''}>Tất cả</option><option value="visible" ${partnerVisibility==='visible'?'selected':''}>Đang hiện</option><option value="hidden" ${partnerVisibility==='hidden'?'selected':''}>Đang ẩn</option></select></div><div class="partner-company-list">${visible.map(x=>`<button type="button" class="partner-company-row ${sel?.id===x.id?'active':''}" data-partner-select="${E(x.id)}"><span class="partner-company-logo" aria-hidden="true">${x.logo?`<img src="${E(imgSrc(x.logo))}" alt="" data-logo-name="${E(x.name)}">`:`${I('building')}`}</span><span class="partner-company-copy"><b>${E(x.name)}</b><small>${E(x.sector||'Chưa có lĩnh vực')} · ${E(x.country||'—')}</small><em class="${window.MDBrandRights?.canDisplayDemo(x)?'status-done':'status-pending'}">${E(partnerState(x))}</em></span><span aria-hidden="true">›</span></button>`).join('')||'<p class="small">Không tìm thấy doanh nghiệp phù hợp.</p>'}</div></div>${sel?`<div class="admin-card partner-detail"><div class="partner-detail-top"><div><div class="eyebrow">COMPANY DEMO</div><h3>${E(sel.name)}</h3><p class="small">Cập nhật hồ sơ và xem trước logo</p></div><span class="pill">#${E(sel.priority)}</span></div><div class="partner-brand-preview"><div class="partner-logo-preview" id="partnerLogoPreview">${sel.logo?`<img src="${E(imgSrc(sel.logo))}" alt="Logo">`:'Chưa có logo'}</div><div><b>Chuẩn hiển thị logo</b><p class="small">Ảnh SVG/PNG/WebP/JPG · <b>180 × 80</b> · Giữ nguyên tỷ lệ, không cắt hoặc kéo giãn.</p><button type="button" class="btn light sm" data-inline-partner="${E(sel.id)}">${I('image','sm')} Đổi logo & xem trước</button></div></div><form id="partnerDetailForm" data-partner-form="${E(sel.id)}"><div class="form-grid"><div class="field"><label for="partner-name">Tên doanh nghiệp *</label><input required id="partner-name" name="name" value="${E(sel.name)}"></div><div class="field"><label for="partner-sector">Ngành nghề</label><input id="partner-sector" name="sector" value="${E(sel.sector)}"></div><div class="field"><label for="partner-country">Quốc gia / khu vực</label><input id="partner-country" name="country" value="${E(sel.country||'')}"></div><div class="field"><label for="partner-priority">Thứ tự trong marquee</label><input id="partner-priority" name="priority" type="number" min="1" max="1000" value="${Number(sel.priority)||1}"></div><div class="field" style="grid-column:span 2"><label for="partner-website">Trang web doanh nghiệp (HTTPS)</label><input id="partner-website" name="website" placeholder="https://..." value="${E(sel.website||'')}"></div><div class="field" style="grid-column:span 2"><label for="partner-logo">Logo URL hoặc file assets</label><input id="partner-logo" name="logo" value="${E(sel.logo||'')}"></div><div class="field" style="grid-column:span 2"><label for="partner-note">Ghi chú nội bộ</label><textarea id="partner-note" name="note" rows="3">${E(sel.note||'')}</textarea></div></div><div class="partner-options"><label class="checkbox-line"><input name="visible" type="checkbox" ${sel.visible?'checked':''}> Hiển thị trên website</label><label class="checkbox-line"><input name="demoLogoVisible" type="checkbox" ${sel.demoLogoVisible?'checked':''}> Hiển thị logo trong demo</label><label class="checkbox-line"><input name="featured" type="checkbox" ${sel.featured?'checked':''}> Ưu tiên hồ sơ tiêu biểu</label></div><div class="partner-form-actions"><button type="button" class="btn light" data-partner-remove="${E(sel.id)}">Xóa hồ sơ</button><button type="submit" class="btn red">${I('save','sm')} Lưu hồ sơ</button></div></form></div>`:'<div class="admin-card">Chọn hoặc tạo hồ sơ doanh nghiệp.</div>'}</div>`}
function openContextImageEditor(slotId,logoPartner){const slot=logoPartner?{id:'partner:'+logoPartner.id,name:'Logo — '+logoPartner.name,src:logoPartner.logo||'',recommend:'PNG/WebP 600 × 240',kind:'logo'}:mediaSlots().find(x=>x.id===slotId);if(!slot)return;const m=logoPartner?{x:50,y:50,zoom:100,brightness:100,contrast:100}:mediaProps(slot.id);const isLogo=slot.kind==='logo';const layer=document.createElement('div');layer.className='modal-layer v7-media-layer';layer.innerHTML=`<div class="v7-studio-dialog"><div class="v7-studio-header"><div><div class="eyebrow">MINH ĐỨC IMAGE STUDIO</div><h2>${E(slot.name)}</h2><p>Tải ảnh hoặc dán liên kết, căn điểm nhìn, xem trước cả hai màn hình.</p></div><button type="button" class="v7-close" data-close-studio aria-label="Đóng">×</button></div><div class="v7-studio-body"><div class="v7-preview-col"><div class="v7-preview-top"><b>Bản xem trước theo bố cục thực tế</b><div class="v7-preview-toggle"><button data-screen="desktop" type="button" class="active">Desktop</button><button data-screen="mobile" type="button">Mobile</button></div></div><div class="v7-display desktop ${isLogo?'is-logo':''}" id="v7StudioDisplay" data-kind="${E(slot.kind)}"><div class="v7-display-image"><img id="v7StudioImage" src="${E(imgSrc(slot.src||'gallery-facility.webp'))}" alt="Xem trước ảnh đang chỉnh" draggable="false"></div>${isLogo?'<span class="v7-logo-preview-text">Kích thước logo chuẩn trong dải đối tác</span>':`<div class="v7-preview-overlay"><small>${slot.kind==='hero'?'NHÂN LỰC LÀ TÀI SẢN':'GÓC NHÌN THƯƠNG HIỆU'}</small><strong>${slot.kind==='hero'?'Nhân lực vững vàng.<br>Doanh nghiệp vươn xa.':E(slot.name)}</strong></div>`}</div><div class="v7-quality" id="v7Quality">Tải ảnh để kiểm tra độ phân giải.</div><div class="v7-editor-tip">${I('image','sm')} Bạn có thể kéo ảnh trực tiếp để thay đổi điểm nhìn. Vùng trắng mô phỏng khoảng chữ được giữ an toàn.</div></div><form id="v7StudioForm" class="v7-controls"><input name="slot" type="hidden" value="${E(slot.id)}"><h3>Nguồn hình ảnh</h3><label class="v7-upload-zone">${I('image')}<b>Chọn ảnh từ máy</b><small>PNG, JPG, WebP · tối đa 8 MB</small><input id="v7ImageFile" type="file" accept="image/jpeg,image/png,image/webp"></label><div class="field"><label for="v7ImageSrc">Hoặc nhập URL HTTPS / tên file trong assets</label><input name="src" id="v7ImageSrc" value="${E(slot.src)}" placeholder="https://example.com/image.jpg"></div><div class="v7-control-divider"></div><h3>Căn chỉnh & chất lượng</h3>${isLogo?`<div class="notice">Logo được hệ thống tự căn giữa, giữ đúng tỷ lệ và giới hạn kích thước; không kéo giãn nhận diện thương hiệu.</div>${[['x',50],['y',50],['zoom',100],['brightness',100],['contrast',100]].map(([key,val])=>`<input type="hidden" name="${key}" value="${val}"><output hidden id="v7Val-${key}"></output>`).join('')}`:[['x','Điểm nhìn ngang',m.x,0,100],['y','Điểm nhìn dọc',m.y,0,100],['zoom','Phóng to',m.zoom,100,170],['brightness','Độ sáng',m.brightness,75,125],['contrast','Tương phản',m.contrast,80,135]].map(([key,label,val,min,max])=>`<label class="v7-slider-label"><span>${label}</span><output id="v7Val-${key}">${val}%</output><input data-v7-slider aria-label="${label}" name="${key}" type="range" min="${min}" max="${max}" value="${val}"></label>`).join('')}<div class="v7-preset-row" ${isLogo?'hidden':''}><button type="button" data-v7-preset="center">Căn giữa</button><button type="button" data-v7-preset="left">Ưu tiên trái</button><button type="button" data-v7-preset="right">Ưu tiên phải</button></div><div class="v7-studio-bottom"><button type="button" class="btn light" data-close-studio>Hủy</button><button class="btn red" type="submit">${I('save','sm')} Lưu & áp dụng</button></div><small class="muted">Ảnh được lưu trên trình duyệt để xem trước trong bản demo. Không thể làm nét ảnh gốc quá nhỏ.</small></form></div></div>`;document.body.append(layer);layer.addEventListener('click',e=>{if(e.target===layer||e.target.closest('[data-close-studio]'))layer.remove()});syncV7Studio(layer);}
function syncV7Studio(layer){const f=layer.querySelector('#v7StudioForm'),img=layer.querySelector('#v7StudioImage'),display=layer.querySelector('#v7StudioDisplay'),source=f.querySelector('[name=src]').value;const vals=Object.fromEntries(['x','y','zoom','brightness','contrast'].map(k=>[k,Number(f.elements[k].value)]));if(img.dataset.src!==source){img.dataset.src=source;img.src=imgSrc(source||'gallery-facility.webp')}img.style.objectPosition=vals.x+'% '+vals.y+'%';img.style.transform=`scale(${vals.zoom/100})`;img.style.filter=`brightness(${vals.brightness/100}) contrast(${vals.contrast/100})`;for(const k of Object.keys(vals))layer.querySelector('#v7Val-'+k).textContent=vals[k]+'%';img.onload=()=>{const msg=layer.querySelector('#v7Quality'),w=img.naturalWidth,h=img.naturalHeight;msg.textContent=w<1100&&!display.classList.contains('is-logo')?`⚠ Ảnh ${w} × ${h}px — có thể mờ trên màn hình lớn. Nên dùng ảnh tối thiểu 1600px.`:`✓ Ảnh ${w} × ${h}px — kiểm tra thêm ở bản preview desktop/mobile.`};img.onerror=()=>{layer.querySelector('#v7Quality').textContent='Không mở được ảnh — kiểm tra URL hoặc tài nguyên ảnh.'}}
let activeMediaSlot='hero';
const mediaSlots=()=>[{id:'hero',name:'Ảnh Hero trang chủ',src:db.home.heroImg||'hero-photo.webp',recommend:'1920 × 900',kind:'hero'},...db.home.gallery.map((x,i)=>({id:'gallery'+i,name:'Ảnh gallery '+(i+1),src:x.src,recommend:i===0?'1200 × 850':'900 × 600',kind:'gallery'})),{id:'video',name:'Poster video công ty',src:db.home.videoPoster||'video-poster.webp',recommend:'1280 × 720',kind:'video'},...db.jobs.map(j=>({id:'job:'+j.id,name:'Việc làm: '+j.title,src:j.image,recommend:'900 × 650',kind:'job'})),...db.posts.map(x=>({id:'post:'+x.id,name:'Bài viết: '+x.title,src:x.cover,recommend:'1200 × 630',kind:'post'}))];
const mediaProps=(key)=>db.mediaTransforms[key]||{x:50,y:50,zoom:100,brightness:100,contrast:100};
function storeMediaSrc(slot,src){if(slot.id==='hero')db.home.heroImg=src;else if(slot.id.startsWith('gallery'))db.home.gallery[Number(slot.id.slice(7))].src=src;else if(slot.id==='video')db.home.videoPoster=src;else if(slot.id.startsWith('job:'))db.jobs.find(j=>j.id===slot.id.slice(4)).image=src;else if(slot.id.startsWith('post:'))db.posts.find(x=>x.id===slot.id.slice(5)).cover=src}
const mediaThumb=(slot)=>`<button class="media-slot ${slot.id===activeMediaSlot?'active':''}" data-media-slot="${E(slot.id)}"><img data-media-key="${E(slot.id)}" src="${E(imgSrc(slot.src))}" alt=""><span>${E(slot.name)}</span></button>`;
function mediaAdmin(){const slots=mediaSlots(),active=slots.find(s=>s.id===activeMediaSlot)||slots[0],m=mediaProps(active.id);return introAdmin('Thư viện media chuyên nghiệp','Upload ảnh, dán URL, căn vùng hiển thị, điều chỉnh ánh sáng và xem bản xem trước cho từng vị trí.',`<a href="index.html" class="btn light" target="_blank">${I('eye','sm')} Xem website</a><button class="btn red" form="mediaV6Form">${I('save','sm')} Lưu ảnh & căn chỉnh</button>`)+`<div class="notice" style="margin-bottom:18px">${I('shield','sm')} Khung hình và tỉ lệ trang được khóa để tránh vỡ layout. Ảnh tải lên được nén sang WebP và lưu cùng nội dung demo trên trình duyệt.</div><div class="admin-card"><h3>Chọn vị trí hiển thị</h3><div class="media-slot-grid">${slots.map(mediaThumb).join('')}</div></div><div class="media-workspace" style="margin-top:16px"><div class="admin-card"><h3>Xem trước: ${E(active.name)}</h3><p class="small">Kích thước ảnh khuyến nghị: ${active.recommend} px. Dùng ảnh gốc sắc nét, không lấy ảnh thu nhỏ từ screenshot.</p><div class="media-preview-frame" id="mediaPreviewFrame"><img id="mediaPreview" src="${E(imgSrc(active.src))}" alt="Ảnh đang chỉnh"></div><p id="mediaQuality" class="small" aria-live="polite">Đang kiểm tra kích thước ảnh…</p><p class="asset-tip" style="margin-top:12px">${I('image','sm')} Kéo vùng ảnh bằng hai thanh vị trí, dùng Zoom để lấp đầy khung. Hạn chế zoom quá 120% khi ảnh nguồn nhỏ.</p></div><form class="admin-card" id="mediaV6Form"><input type="hidden" name="slot" value="${E(active.id)}"><h3>Chỉnh sửa hình ảnh</h3><div class="field"><label>URL ảnh hoặc đường dẫn assets/</label><input id="mediaSource" name="src" value="${E(active.src)}" placeholder="https://... hoặc tên tệp.jpg"></div><div class="field" style="margin-top:14px"><label>Hoặc upload từ máy</label><input id="mediaFile" type="file" accept="image/jpeg,image/png,image/webp" style="height:auto;padding:10px"></div><p class="small">Ảnh tối đa 8MB trước khi nén; lưu vào nội dung demo trên trình duyệt.</p>${[['x','Căn ngang',m.x,0,100],['y','Căn dọc',m.y,0,100],['zoom','Phóng ảnh',m.zoom,100,155],['brightness','Độ sáng',m.brightness,75,125],['contrast','Tương phản',m.contrast,80,135]].map(([id,label,val,min,max])=>`<div class="media-setting"><label for="ctrl-${id}">${label}</label><input id="ctrl-${id}" name="${id}" data-media-range type="range" min="${min}" max="${max}" value="${val}"><output id="v-${id}">${val}%</output></div>`).join('')}<button class="btn light full" type="button" data-media-reset style="margin:17px 0 10px">Đặt lại căn ảnh chuẩn</button><button class="btn red full" type="submit">Lưu & xem trên website</button><div class="field" style="margin-top:22px"><label>Link video giới thiệu doanh nghiệp</label><input name="videoUrl" value="${E(db.home.videoUrl||'')}" placeholder="YouTube hoặc MP4"></div></form></div>`}
function partnerAdmin(){return premiumPartnerAdmin()}
function overviewAdmin(){return introAdmin('Quản lý nội dung','Chọn phần cần chỉnh sửa, lưu và xem trước ngay trên website.',`<a class="btn light" href="index.html" target="_blank">${I('eye','sm')} Xem website</a><button class="btn red" data-admin="jobs">${I('plus','sm')} Quản lý tuyển dụng</button>`)+`<div class="cms-metric-grid"><div class="cms-metric"><strong>${db.jobs.length}</strong><span>Tin tuyển dụng</span></div><div class="cms-metric"><strong>${db.jobs.filter(x=>x.open).length}</strong><span>Đang hiển thị</span></div><div class="cms-metric"><strong>${db.posts.length}</strong><span>Bài viết & video</span></div><div class="cms-metric"><strong>${db.partners.length}</strong><span>Hồ sơ doanh nghiệp</span></div></div><h3 style="margin:28px 0 13px">Truy cập nhanh</h3><div class="cms-quick-grid">${[['home','Trang chủ','Nội dung, hình ảnh và 4 ngôn ngữ'],['partners','Doanh nghiệp mẫu','Logo, hồ sơ và bản xem trước'],['jobs','Tuyển dụng','Biên tập 4 mục và bản dịch'],['posts','Bài viết & SEO','Content Assistant, hình ảnh, SEO và bản dịch']].map(([k,t,d])=>`<button class="cms-quick" data-admin="${k}">${I(k==='media'?'image':k==='partners'?'building':k==='seo'?'spark':'file')}<span>${t}<br><small>${d}</small></span></button>`).join('')}</div>`}

const langStatuses=(kind,id)=>{const record=db.i18n[kind+':'+id]||{};return `<div class="status-list">${[['vi','🇻🇳 Tiếng Việt (Nguồn)'],['en','🇬🇧 English'],['zh','🇨🇳 中文'],['ko','🇰🇷 한국어']].map(([k,t])=>`<div class="status-item"><b>${t}</b><span class="pill ${k==='vi'||record[k]?.status==='translated'?'success':'neutral'}">${k==='vi'?'Nguồn':record[k]?.status==='needs-review'?'Nguồn đã đổi · Cần rà lại':record[k]?.status==='translated'?'Đã hiệu đính':sampleTranslation(k,kind,id,kind==='home'?'heroLine1':'title')?'Có bản dịch demo':'Dùng tiếng Việt'}</span></div>`).join('')}</div>`};
function inlineTranslationFields(kind,id,fields,record,lang){const data=db.i18n[kind+':'+id]?.[lang]||{};return fields.map(f=>`<div class="field"><label>${E(f)} <small class="muted">· VI: ${E(String(record[f]||'').slice(0,66))}</small></label><textarea data-l10n-key="${E(f)}" rows="${['body','benefits','description','requirements','apply','heroIntro','aboutIntro'].includes(f)?4:2}" placeholder="Trống = dùng tiếng Việt">${E(data[f]||sampleTranslation(lang,kind,id,f)||'')}</textarea></div>`).join('')}
function inlineTranslationPanel(kind,id,fields,record){return `<div class="admin-card integrated-translation" data-l10n-kind="${E(kind)}" data-l10n-id="${E(id)}" data-l10n-fields="${E(fields.join(','))}"><h3>${I('globe','sm')} Bản dịch ngay trong nội dung</h3><p class="small">Chọn ngôn ngữ và chỉnh bản dịch để xem trước. Nếu thiếu bản dịch, website dùng tiếng Việt.</p>${langStatuses(kind,id)}<div class="field l10n-language"><label>Chọn bản dịch</label><select data-l10n-lang><option value="en">English</option><option value="zh">中文 (Giản thể)</option><option value="ko">한국어</option></select></div><div class="l10n-fields">${inlineTranslationFields(kind,id,fields,record,'en')}</div><div class="row between l10n-footer"><span class="small">Nếu không có bản dịch, giữ nội dung tiếng Việt.</span><button type="button" class="btn blue" data-l10n-save>${I('save','sm')} Lưu bản dịch EN/ZH/KO</button></div></div>`}
function translationsAdmin(){return introAdmin('Quản lý đa ngôn ngữ','Tiếng Việt là nguồn. Dịch tự động khi lưu; cho phép hiệu đính bản dịch từng trường.',`<button data-retranslate class="btn red">${I('globe','sm')} Dịch lại nội dung</button>`)+`<div class="editor-layout"><div class="stack"><div class="admin-card"><h3>Chọn nội dung</h3><div class="field"><label>Loại tài liệu</label><select id="transEntity"><option value="home:main">Trang chủ</option>${db.jobs.map(j=>`<option value="job:${E(j.id)}">Việc làm · ${E(j.title)}</option>`).join('')}${db.posts.map(p=>`<option value="post:${E(p.id)}">Bài viết · ${E(p.title)}</option>`).join('')}</select></div><div class="field" style="margin-top:13px"><label>Ngôn ngữ cần hiệu đính</label><select id="transLang"><option value="en">English (EN)</option><option value="zh">中文 (ZH)</option><option value="ko">한국어 (KO)</option></select></div></div><div id="transFields" class="admin-card"></div></div><div class="stack"><div class="admin-card"><h3>Cấu hình dịch tự động</h3><div class="field"><label>CMS_ADMIN_TOKEN (dùng khi chạy backend mẫu)</label><input id="adminToken" type="password" autocomplete="off" placeholder="Không đưa API key vào trình duyệt" value="${E(adminToken)}"></div><div class="notice warn" style="margin-top:12px">Mở file HTML trực tiếp: không có dịch vụ dịch AI. Khi lưu, trang sẽ dùng bản tiếng Việt; không tự tạo bản dịch giả.</div></div><div class="admin-card"><h3>Quy trình nội dung</h3><p>1. Soạn và lưu nội dung tiếng Việt.</p><p>2. Backend dịch EN / ZH / KO.</p><p>3. Nhân viên hiệu đính nếu cần.</p><p>4. Dịch lỗi / chưa có bản dịch: website hiển thị tiếng Việt.</p><p class="small">Các bản dịch lưu trên trình duyệt trong prototype, không đồng bộ giữa các máy.</p></div></div></div>`}
function transDoc(){const key=qs('#transEntity')?.value||'home:main',lang=qs('#transLang')?.value||'en';const [type,id]=key.split(':');const record=type==='home'?db.home:type==='job'?db.jobs.find(x=>x.id===id):db.posts.find(x=>x.id===id);if(!record)return;const keys=type==='home'?['heroLine1','heroLine2','heroIntro','aboutTitle','aboutIntro','galleryTitle','videoTitle','videoIntro']:type==='job'?['title','description','requirements','benefits','apply']:['title','excerpt','body','seoTitle','meta'];let existing=db.i18n[key]?.[lang]||{};qs('#transFields').innerHTML=`<h3>Hiệu đính ${lang.toUpperCase()}</h3><p class="small">Để trống sẽ dùng nội dung tiếng Việt nguồn.</p><form id="manualTranslation" class="stack">${keys.map(f=>`<div class="field"><label>${f} · Nguồn: ${E(String(record[f]||'').slice(0,90))}</label><textarea name="${f}" rows="${['description','requirements','body','benefits'].includes(f)?5:2}">${E(existing[f]||'')}</textarea></div>`).join('')}<button class="btn blue" type="submit">${I('save','sm')} Lưu bản dịch hiệu đính</button></form>`}
function seoAdmin(){return introAdmin('Trợ lý nội dung & SEO','Gợi ý cấu trúc bài viết, tiêu đề và mô tả tìm kiếm. Không tự đăng Facebook/TikTok.')+`<div class="editor-layout"><div class="stack"><div class="admin-card"><h3>${I('spark')} AI gợi ý content chuẩn SEO</h3><form id="seoForm" class="form-fields"><div class="field"><label>Tiêu đề / Chủ đề *</label><input name="title" required placeholder="Ví dụ: Hướng dẫn ứng tuyển tại KCN Yên Phong"></div><div class="field"><label>Từ khóa chính</label><input name="keyword" placeholder="Việc làm KCN Yên Phong"></div><div class="field"><label>Mô tả bối cảnh / dữ kiện</label><textarea name="brief" placeholder="Nêu thông tin đã được kiểm chứng; không bịa số lương hoặc tên đối tác."></textarea></div><button class="btn red" type="submit">${I('spark','sm')} Tạo gợi ý</button></form></div><div class="admin-card" id="seoOutput"><h3>Kết quả gợi ý</h3><div class="notice">Nếu chưa cấu hình AI, công cụ sẽ tạo mẫu SEO theo quy tắc để nhân viên biên tập tiếp.</div></div></div><div class="stack"><div class="admin-card"><h3>Kiểm tra SEO trước khi đăng</h3><p>${I('check','sm')} Tiêu đề phản ánh đúng bài viết.</p><p>${I('check','sm')} URL ngắn gọn, không dấu.</p><p>${I('check','sm')} Có mô tả tìm kiếm riêng.</p><p>${I('check','sm')} Ảnh có nội dung ALT.</p><p>${I('check','sm')} Nội dung và doanh nghiệp được xác minh.</p><div class="notice">AI tạo bản nháp, nhân viên cần duyệt trước khi công khai.</div></div></div></div>`+seoAudit()}
function seoAudit(){const score=(p)=>Math.min(100,(p.title?.length>15?20:0)+(p.meta?.length>65?25:10)+(p.keyword?.length>3?15:0)+(p.cover?20:0)+(p.body?.length>150?20:0));return `<div class="admin-card" style="margin-top:20px"><h3>SEO Quality Monitor · Bài viết hiện tại</h3><p class="small">Điểm kiểm tra theo quy tắc (demo), không phải điểm xếp hạng Google.</p><table class="admin-table"><thead><tr><th>Bài viết</th><th>SEO Score</th><th>Gợi ý</th><th></th></tr></thead><tbody>${db.posts.map(p=>`<tr><td><b>${E(p.title)}</b></td><td><span class="pill ${score(p)>=75?'success':'neutral'}">${score(p)}/100</span></td><td>${p.meta?.length<65?'Bổ sung meta description':p.keyword?.length<3?'Thêm từ khóa chính':'Nên kiểm tra nội dung'}</td><td><button data-edit-post="${E(p.id)}">Tối ưu</button></td></tr>`).join('')}</tbody></table></div>`}
function settingsAdmin(){return introAdmin('Cài đặt liên hệ & dữ liệu','Quản lý kênh hỗ trợ và nội dung của bản prototype.')+window.MDExperience.settingsHtml(db)+`<div class="admin-card"><h2>Dữ liệu mẫu</h2><p>Dùng bản sao JSON để lưu hoặc chuyển nội dung demo sang trình duyệt khác. Video tải từ máy không nằm trong JSON; giữ tệp video gốc để tải lại hoặc dùng liên kết HTTPS.</p><div class="cms-toolbar"><button class="btn blue" type="button" data-export>${I('save','sm')} Xuất nội dung</button><label class="btn light" style="cursor:pointer">${I('upload','sm')} Nhập nội dung<input type="file" accept="application/json,.json" data-import style="display:none"></label><button class="btn light" id="resetDemo">Đặt lại bản demo</button></div></div>`}
function protectCmsFields(root){
 const limits={heroLine1:65,heroLine2:65,heroIntro:360,aboutTitle:160,aboutIntro:1100,
   galleryTitle:120,videoTitle:120,videoIntro:500,title:140,company:160,
   excerpt:290,seoTitle:70,meta:165,slug:160};
 root.querySelectorAll('input[name],textarea[name]').forEach(input=>{
  const key=input.name;if(key.startsWith('galleryCaption'))limits[key]=90;if(!Object.prototype.hasOwnProperty.call(limits,key))return;
  const limit=limits[key];input.maxLength=limit;
  if(input.parentElement?.querySelector('.cms-char-count'))return;
  const counter=document.createElement('small');counter.className='cms-char-count';
  const sync=()=>{counter.textContent=input.value.length+' / '+limit;counter.classList.toggle('is-over',input.value.length>limit)};
  input.addEventListener('input',sync);sync();input.parentElement?.appendChild(counter);
 });
}
function renderAdmin(){const el=qs('#adminContent');if(!el)return;window.MDExperience.releaseEditors();if(['media','seo','translations'].includes(adminTab))adminTab=adminTab==='seo'?'posts':'home';el.innerHTML=adminTab==='overview'?overviewAdmin():adminTab==='company'?(window.MDCompanyProfile?.settingsHtml(db)||''):adminTab==='partners'?partnerAdmin():adminTab==='home'?homeAdmin():adminTab==='jobs'?jobsAdmin():adminTab==='job-edit'?jobEditor():adminTab==='posts'?postsAdmin():adminTab==='post-edit'?postEditor():settingsAdmin();qsa('.admin-nav button').forEach(b=>b.classList.toggle('selected',b.dataset.admin===(adminTab==='job-edit'?'jobs':adminTab==='post-edit'?'posts':adminTab)));protectCmsFields(el);enhanceCms();protectImages();window.MD15?.enhanceCms(el);window.MDExperience.mountEditors(el);applyImageTransforms();}
async function autoTranslate(kind,id,source={},previous={}){
  const key=kind+':'+id,bundle=db.i18n[key]||={};
  const changed=Object.keys(source).filter(field=>source[field]!==previous[field]);
  if(!changed.length)return;
  bundle.__dirty=true;
  for(const lang of ['en','zh','ko']){
    const translation=bundle[lang]||={};
    // Retain both human edits and the old sample text for review. Never silently
    // replace an edited translation when its Vietnamese source changes.
    for(const field of Object.keys(source))if(!translation[field])translation[field]=sampleTranslation(lang,kind,id,field);
    translation.reviewFields=[...new Set([...(translation.reviewFields||[]),...changed])];
    translation.status='needs-review';
  }
  bundle.__source={...source};persist();qsa('[data-l10n-kind]').filter(panel=>panel.dataset.l10nKind===kind&&panel.dataset.l10nId===id).forEach(panel=>{const status=panel.querySelector('.status-list');if(status)status.outerHTML=langStatuses(kind,id);});
  notify('Đã giữ nguyên các bản dịch. Những trường có nguồn thay đổi cần được rà lại.');
}
function saveHome(form){const d=new FormData(form),h=db.home;const original=JSON.stringify(Object.fromEntries(["heroLine1", "heroLine2", "heroIntro", "aboutTitle", "aboutIntro", "galleryTitle", "videoTitle", "videoIntro"].map(k=>[k,h[k]])));if(d.has('videoUrl'))h.videoUrl=String(d.get('videoUrl')||'');for(const k of ['heroLine1','heroLine2','heroIntro','aboutTitle','aboutIntro','galleryTitle','videoTitle','videoIntro','heroImg']){const val=d.get(k);if(val!==null)h[k]=String(val||'').trim()};h.kpi=h.kpi.map((x,i)=>String(d.get('kpi'+i)||x));h.gallery.forEach((im,i)=>{if(d.has('galleryCaption'+i))im.caption=String(d.get('galleryCaption'+i)||'').trim()});for(const k in h.sections)h.sections[k]=d.get('section_'+k)==='on';audit('Cập nhật nội dung trang chủ');if(!persist())return;notify('Đã lưu trang chủ.');if(original!==JSON.stringify(Object.fromEntries(["heroLine1", "heroLine2", "heroIntro", "aboutTitle", "aboutIntro", "galleryTitle", "videoTitle", "videoIntro"].map(k=>[k,h[k]]))))autoTranslate('home','main',Object.fromEntries(["heroLine1", "heroLine2", "heroIntro", "aboutTitle", "aboutIntro", "galleryTitle", "videoTitle", "videoIntro"].map(k=>[k,h[k]])),JSON.parse(original))}
function saveJob(form){const d=new FormData(form),j=db.jobs.find(x=>x.id===editJobId);if(!j)return;const original=JSON.stringify(Object.fromEntries(["title", "description", "requirements", "benefits", "apply"].map(k=>[k,j[k]])));for(const k of ['title','company','location','park','posted','image','description','requirements','benefits','apply','slug'])j[k]=String(d.get(k)||'').trim();for(const k of ['min','max','openings'])j[k]=Number(d.get(k)||0);j.type=String(d.get('type')||'worker');j.urgent=d.get('urgent')==='on';j.open=d.get('open')==='true';j.tags=String(d.get('tags')||'').split(',').map(x=>x.trim()).filter(Boolean);if(j.max<j.min){notify('Mức lương tối đa phải lớn hơn tối thiểu.');return}audit('Sửa tin tuyển dụng: '+j.title);persist();notify('Đã lưu tin tuyển dụng.');if(original!==JSON.stringify(Object.fromEntries(["title", "description", "requirements", "benefits", "apply"].map(k=>[k,j[k]]))))autoTranslate('job',j.id,Object.fromEntries(["title", "description", "requirements", "benefits", "apply"].map(k=>[k,j[k]])),JSON.parse(original))}
function savePost(form){const d=new FormData(form),p=db.posts.find(x=>x.id===editPostId);if(!p)return;const original=JSON.stringify(Object.fromEntries(["title", "excerpt", "body", "seoTitle", "meta"].map(k=>[k,p[k]])));for(const k of ['title','category','date','excerpt','body','cover','video','seoTitle','meta','keyword','type'])p[k]=String(d.get(k)||'').trim();p.visible=d.get('visible')==='on';audit('Sửa bài viết: '+p.title);persist();notify('Đã lưu bài viết.');if(original!==JSON.stringify(Object.fromEntries(["title", "excerpt", "body", "seoTitle", "meta"].map(k=>[k,p[k]]))))autoTranslate('post',p.id,Object.fromEntries(["title", "excerpt", "body", "seoTitle", "meta"].map(k=>[k,p[k]])),JSON.parse(original))}
function saveMedia(form){const d=new FormData(form);db.home.gallery.forEach((im,i)=>{im.src=String(d.get('img'+i)||im.src).trim();im.caption=String(d.get('caption'+i)||'').trim()});db.home.videoUrl=String(d.get('videoUrl')||'').trim();persist();notify('Đã lưu thư viện ảnh/video.');renderAdmin()}
function updateMediaPreview(){const src=qs('#mediaSource')?.value||'',img=qs('#mediaPreview');if(!img)return;img.onload=()=>{const w=img.naturalWidth,h=img.naturalHeight;const min=activeMediaSlot==='hero'?1200:700;const note=qs('#mediaQuality');if(note)note.textContent=(!img.src.startsWith('data:')&&(/^assets\//.test(img.getAttribute('src')||'')))?`⚠ Đây là ảnh minh họa cắt từ thiết kế V5, đã được phóng lớn; để sắc nét thật, hãy thay bằng ảnh gốc tối thiểu ${min}px.`:w<min?`⚠ Ảnh nguồn ${w} × ${h} px khá nhỏ. Nên upload ảnh gốc tối thiểu ${min}px.`:`✓ Ảnh ${w} × ${h} px — đủ độ phân giải để xem thử.`};img.src=imgSrc(src);const vals={};for(const k of ['x','y','zoom','brightness','contrast']){vals[k]=Number(qs('#ctrl-'+k)?.value||50);const out=qs('#v-'+k);if(out)out.textContent=vals[k]+'%'}img.style.objectPosition=vals.x+'% '+vals.y+'%';img.style.transform='scale('+(vals.zoom/100)+')';img.style.filter='brightness('+(vals.brightness/100)+') contrast('+(vals.contrast/100)+')'}
async function compressMediaFile(file){const bitmap=await createImageBitmap(file);const ratio=Math.min(1,1500/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*ratio);canvas.height=Math.round(bitmap.height*ratio);const ctx=canvas.getContext('2d');ctx.imageSmoothingQuality='high';ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close?.();return canvas.toDataURL('image/webp',.76)}
function saveMediaV6(form){const d=new FormData(form),slot=mediaSlots().find(s=>s.id===String(d.get('slot')));if(!slot)return;const src=String(d.get('src')||'').trim();if(!src||!(/^(https:\/\/|data:image\/|[a-zA-Z0-9_-]+\.(png|jpe?g|webp)$)/i.test(src))){notify('URL ảnh phải là HTTPS hoặc tên tệp ảnh hợp lệ.');return}storeMediaSrc(slot,src);db.mediaTransforms[slot.id]=Object.fromEntries(['x','y','zoom','brightness','contrast'].map(k=>[k,Number(d.get(k)||50)]));db.home.videoUrl=String(d.get('videoUrl')||'').trim();audit('Chỉnh ảnh: '+slot.name);persist();notify('Đã lưu ảnh và vị trí cắt.');renderAdmin()}
function applyImageTransforms(){
  const set=(el,m)=>{if(!el||!m)return;el.style.objectPosition=`${m.x??50}% ${m.y??50}%`;el.style.transform=`scale(${(m.zoom??100)/100})`;el.style.filter=`brightness(${(m.brightness??100)/100}) contrast(${(m.contrast??100)/100})`;};
  qsa('img[data-media-key]').forEach(img=>set(img,mediaProps(img.dataset.mediaKey)));
  const hero=db.mediaTransforms.hero;set(qs('.md-hero-img'),hero);
  if(hero){document.documentElement.style.setProperty('--hero-x',(hero.x??50)+'%');document.documentElement.style.setProperty('--hero-y',(hero.y??50)+'%');}
  qsa('.gallery-grid img').forEach((img,i)=>set(img,db.mediaTransforms['gallery'+i]));
  const currentId=new URLSearchParams(location.search).get('id');
  set(qs('.v14-detail-main-image img'),db.mediaTransforms['job:'+currentId]);
}
function openImage(url,caption){const layer=document.createElement('div');layer.className='modal-layer';layer.innerHTML=`<div class="modal-card" style="width:min(900px,100%)"><button class="modal-close" aria-label="${C('close')}">×</button><img src="${E(url)}" alt="${E(caption)}" style="width:100%;border-radius:12px"><p style="margin:12px 0 0">${E(caption)}</p></div>`;document.body.append(layer);window.MDTranslate?.apply(currentLang,layer);focusDialog(layer);layer.addEventListener('click',e=>{if(e.target===layer||e.target.closest('.modal-close'))layer.remove()})}
function openVideo(url){const layer=document.createElement('div');layer.className='modal-layer';layer.innerHTML=`<div class="modal-card md-video-modal" style="width:min(860px,100%)"><button class="modal-close" aria-label="${C('close')}">×</button><h3>${V('videos')}</h3><div class="md-video-player" role="status"></div></div>`;document.body.append(layer);focusDialog(layer);window.MDExperience.player(layer.querySelector('.md-video-player'),url,{autoplay:true});layer.addEventListener('click',e=>{if(e.target===layer||e.target.closest('.modal-close'))layer.remove()})}

function saveContextStudio(form){const d=new FormData(form),key=String(d.get('slot')),src=String(d.get('src')||'').trim();if(!validMediaSource(src)){notify('Hãy dùng ảnh tải lên, URL HTTPS hoặc tên tệp assets hợp lệ.');return}const transform=Object.fromEntries(['x','y','zoom','brightness','contrast'].map(k=>[k,Number(d.get(k))]));if(key.startsWith('partner:')){const p=db.partners.find(x=>x.id===key.slice(8));if(p){p.logo=src;p.approved=false;}}else{const slot=mediaSlots().find(s=>s.id===key);if(!slot)return;storeMediaSrc(slot,src);db.mediaTransforms[key]=transform;}audit('Chỉnh ảnh theo ngữ cảnh: '+key);persist();document.querySelector('.v7-media-layer')?.remove();document.querySelectorAll('[data-inline-media]').forEach(b=>{if(b.dataset.inlineMedia===key){const im=b.closest('.context-media')?.querySelector('.context-media-image img');if(im){im.src=imgSrc(src);applyImageTransforms()}}});const field=key.startsWith('job:')?document.querySelector('#jobEditForm [name=image]'):key.startsWith('post:')?document.querySelector('#postEditForm [name=cover]'):document.querySelector('#homeEditForm [name=heroImg]');if(field)field.value=src;if(key.startsWith('partner:')){const field=document.querySelector('#partnerDetailForm [name=logo]');if(field)field.value=src;const display=document.querySelector('#partnerLogoPreview');if(display)display.innerHTML=`<img src="${E(imgSrc(src))}" alt="Logo">`;if(display)protectImages(display);const partner=db.partners.find(p=>p.id===key.slice(8)),row=qsa('[data-partner-select]').find(el=>el.dataset.partnerSelect===key.slice(8)),mark=row?.querySelector('.partner-company-logo');if(mark){mark.innerHTML=`<img src="${E(imgSrc(src))}" alt="" data-logo-name="${E(partner?.name||'')}">`;protectImages(mark);}}notify('Đã lưu ảnh & căn chỉnh. Các nội dung đang nhập vẫn được giữ nguyên.');}
function wireV7(){document.addEventListener('input',e=>{const layer=e.target.closest('.v7-media-layer');if(layer&&(e.target.matches('[data-v7-slider]')||e.target.id==='v7ImageSrc'))syncV7Studio(layer);if(e.target.id==='partnerSearch'){partnerQuery=e.target.value;const field=document.activeElement;renderAdmin();const next=qs('#partnerSearch');if(next){next.focus();next.setSelectionRange(partnerQuery.length,partnerQuery.length)}}if(e.target.closest('#partnerDetailForm')&&e.target.name==='logo'){const image=qs('#partnerLogoPreview');if(image){image.innerHTML=e.target.value?`<img src="${E(imgSrc(e.target.value))}" alt="Logo">`:'Chưa có logo';protectImages(image)}}});document.addEventListener('change',async e=>{if(e.target.id==='partnerVisibility'){partnerVisibility=e.target.value;renderAdmin();return}if(e.target.id==='v7ImageFile'){const file=e.target.files?.[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>8*1024*1024){notify('Chỉ chọn JPG, PNG hoặc WebP dưới 8MB.');return}const layer=e.target.closest('.v7-media-layer');try{layer.querySelector('#v7ImageSrc').value=await compressMediaFile(file);syncV7Studio(layer);notify('Ảnh đã nạp vào vùng xem trước.')}catch{notify('Không đọc được ảnh này.')}return}});document.addEventListener('click',e=>{const layer=e.target.closest('.v7-media-layer');if(!layer)return;const screen=e.target.closest('[data-screen]');if(screen){layer.querySelectorAll('[data-screen]').forEach(x=>x.classList.toggle('active',x===screen));const disp=layer.querySelector('#v7StudioDisplay');disp.classList.toggle('mobile',screen.dataset.screen==='mobile');disp.classList.toggle('desktop',screen.dataset.screen!=='mobile');return}const preset=e.target.closest('[data-v7-preset]');if(preset){const f=layer.querySelector('#v7StudioForm');f.elements.x.value=preset.dataset.v7Preset==='left'?25:preset.dataset.v7Preset==='right'?75:50;f.elements.y.value=50;syncV7Studio(layer);return}});let dragging=false,prevX=0,prevY=0;document.addEventListener('pointerdown',e=>{const target=e.target.closest('.v7-display-image');if(!target)return;dragging=true;prevX=e.clientX;prevY=e.clientY;target.setPointerCapture?.(e.pointerId)});document.addEventListener('pointermove',e=>{if(!dragging)return;const layer=e.target.closest('.v7-media-layer');if(!layer)return;const f=layer.querySelector('#v7StudioForm');f.elements.x.value=Math.max(0,Math.min(100,Number(f.elements.x.value)-(e.clientX-prevX)/3));f.elements.y.value=Math.max(0,Math.min(100,Number(f.elements.y.value)-(e.clientY-prevY)/3));prevX=e.clientX;prevY=e.clientY;syncV7Studio(layer)});document.addEventListener('pointerup',()=>dragging=false);}
