function updateFlagshipSEO(){
 const visibleHeading=[...document.querySelectorAll('main h1')].find(el=>!el.closest('[hidden]'));if(visibleHeading)document.title=visibleHeading.textContent.trim().replace(/\s+/g,' ')+' | Minh Đức';
 document.documentElement.lang=['vi','en','zh','ko'].includes(currentLang)?currentLang:'vi';
 const previous=document.getElementById('md-v12-schema');if(previous)previous.remove();
 // Prototype remains noindex. Only emit production structured data after verified deployment config.
 if(!window.MD_PRODUCTION?.verified||!window.MD_PRODUCTION?.canonicalOrigin)return;
 const cfg=window.MD_PRODUCTION,origin=String(cfg.canonicalOrigin).replace(/\/$/,'');
 if(!/^https:\/\//.test(origin))return;
 const graph=[{'@type':'Organization','@id':origin+'/#organization','name':cfg.organizationName||'Minh Đức','url':origin+'/'}];
 if(page==='home')graph.push({'@type':'FAQPage','@id':origin+'/#faq','mainEntity':[
  {'@type':'Question','name':'Có cần tải CV khi ứng tuyển công việc phổ thông?','acceptedAnswer':{'@type':'Answer','text':'Các vị trí lao động phổ thông không yêu cầu CV trong biểu mẫu đăng ký nhanh.'}},
  {'@type':'Question','name':'Thông tin đăng ký được gửi đi đâu?','acceptedAnswer':{'@type':'Answer','text':'Thông tin được xử lý theo chính sách bảo vệ dữ liệu được công bố trên website chính thức.'}}
 ]});
 if(page==='detail'){
  const job=db.jobs.find(j=>j.id===new URLSearchParams(location.search).get('id'));
  if(job && job.verified===true && job.open===true && job.min>0 && job.max>=job.min && job.location && job.company && job.posted){
    graph.push({'@type':'JobPosting','@id':origin+'/chi-tiet-viec-lam.html?id='+encodeURIComponent(job.id)+'#job',
      'title':job.title,'description':job.description,'datePosted':job.posted,'employmentType':'FULL_TIME',
      'hiringOrganization':{'@type':'Organization','name':job.company},
      'jobLocation':{'@type':'Place','address':{'@type':'PostalAddress','addressLocality':job.location,'addressCountry':'VN'}},
      'baseSalary':{'@type':'MonetaryAmount','currency':'VND','value':{'@type':'QuantitativeValue','minValue':job.min*1000000,'maxValue':job.max*1000000,'unitText':'MONTH'}}});
  }
 }
 const script=document.createElement('script');script.id='md-v12-schema';script.type='application/ld+json';script.textContent=JSON.stringify({'@context':'https://schema.org','@graph':graph}).replace(/</g,'\\u003c');document.head.appendChild(script);
}
let flagshipObserver;
function observeFlagship(){flagshipObserver?.disconnect();const nodes=document.querySelectorAll('.kpi, .job-card, .news-card');if(!('IntersectionObserver' in window)||matchMedia('(prefers-reduced-motion: reduce)').matches){nodes.forEach(n=>n.classList.add('in-view'));return;}flagshipObserver=new IntersectionObserver(items=>items.forEach(it=>{if(it.isIntersecting){it.target.classList.add('in-view');flagshipObserver.unobserve(it.target)}}),{threshold:.12});nodes.forEach((n,i)=>{n.classList.add('reveal-item');n.style.setProperty('--stagger',Math.min(i%4,3)*70+'ms');flagshipObserver.observe(n)})}

