 const name=form.elements.namedItem('name'),phone=form.elements.namedItem('phone'),consent=form.elements.namedItem('consent');if(name&&name.value.trim().length<2)error(name,C('nameError'));if(phone&&!/^(0|\+84)[35789]\d{8}$/.test(phone.value.replace(/[\s.-]/g,'')))error(phone,C('phoneError'));if(consent&&!consent.checked)error(consent,C('consentError'));
