function validImport(obj){
 if(obj?.companyProfileRevision===27&&!Array.isArray(obj.partners))return false;
 if(!obj||typeof obj!=='object'||!Array.isArray(obj.jobs)||!Array.isArray(obj.posts)||!obj.home||!Array.isArray(obj.home.gallery)||!Array.isArray(obj.home.kpi)||!obj.home.sections)return false;
 if(obj.jobs.length>250||obj.posts.length>250||obj.home.gallery.length>20||!obj.jobs.every(j=>j&&['id','title','company','location','park','description','requirements','benefits','apply','posted'].every(k=>typeof j[k]==='string')&&['worker','internal'].includes(j.type)&&Number.isFinite(j.min)&&Number.isFinite(j.max)&&j.min>=0&&j.max>=j.min&&typeof j.open==='boolean'&&Array.isArray(j.tags)))return false;
 if(!obj.posts.every(p=>p&&['id','title','excerpt','body','cover','date'].every(k=>typeof p[k]==='string')&&typeof p.visible==='boolean'))return false;
 if(!obj.home.gallery.every(p=>p&&typeof p.src==='string'&&typeof p.caption==='string'))return false;
 if(obj.partners&&(!Array.isArray(obj.partners)||obj.partners.length>250||!obj.partners.every(p=>p&&typeof p.id==='string'&&typeof p.name==='string')))return false;
 if(window.MDCompanyProfile&&!window.MDCompanyProfile.valid(obj))return false;
 const walk=(v,depth=0)=>{if(depth>8)return false;if(typeof v==='string')return v.startsWith('data:image/')?v.length<2000000:v.length<=12000;if(v===null||typeof v!=='object')return true;return Object.entries(v).every(([k,x])=>!['__proto__','prototype','constructor'].includes(k)&&walk(x,depth+1));};return walk(obj);
}
