function filteredJobs(params){const term=normalizeSearch(params.get('q')).trim(),area=params.get('area'),park=params.get('park'),min=Number(params.get('salary')||0),onlySaved=params.get('saved')==='1',type=jobsRoute().tab;return db.jobs.filter(j=>j.open&&j.type===type&&(!onlySaved||savedJobs.has(j.id))).filter(j=>(!term||normalizeSearch([j.title,localize('job',j.id,'title',j.title),j.company,j.park,j.location].join(' ')).includes(term))&&(!area||j.location===area)&&(!park||j.park===park)&&(!min||j.max>=min)).sort((a,b)=>sortKey==='high'?b.max-a.max:sortKey==='low'?a.min-b.min:sortKey==='urgent'?Number(b.urgent)-Number(a.urgent)||b.posted.localeCompare(a.posted):b.posted.localeCompare(a.posted));}
