function syncComparison(){comparison=new Set([...comparison].filter(id=>db.jobs.some(j=>j.id===id&&j.open)));try{sessionStorage.setItem('md_compare_jobs',JSON.stringify([...comparison]));}catch{}qsa('[data-compare-job]').forEach(b=>{const chosen=comparison.has(b.dataset.compareJob);b.setAttribute('aria-pressed',String(chosen));const label=b.querySelector('span');if(label)label.textContent=V(chosen?'selected':'compare');const svg=b.querySelector('svg');if(svg)svg.innerHTML=icons[chosen?'check':'plus'];});let tray=qs('#compareTray');if(!comparison.size){tray?.remove();return;}if(!tray){tray=document.createElement('aside');tray.id='compareTray';tray.className='v14-compare-tray';tray.setAttribute('aria-label',V('compare'));document.body.append(tray);}tray.innerHTML=`<div class="v14-tray-summary"><strong>${comparison.size} / 3</strong><span>${V('compareHint')}</span></div><button class="v14-text-button" type="button" data-clear-comparison>${V('clearSelection')}</button><button class="btn red" type="button" data-open-comparison ${comparison.size<2?'disabled':''}>${V('compareNow')}${I('arrow','sm')}</button>`;}
function openComparison(){if(comparison.size<2)return;const jobs=[...comparison].map(id=>db.jobs.find(j=>j.id===id&&j.open)).filter(Boolean);const layer=document.createElement('div');layer.className='modal-layer';layer.innerHTML=`<div class="modal-card v14-compare-dialog"><button type="button" class="modal-close" aria-label="${V('close')}">×</button><div class="eyebrow">${V('compare')}</div><h2>${V('compareTitle')}</h2><p class="muted">${V('compareIntro')}</p><div class="v14-compare-grid" style="--compare-count:${jobs.length}">${jobs.map(j=>`<article class="v14-compare-column"><img data-media-key="job:${E(j.id)}" src="${E(imgSrc(j.image))}" width="600" height="338" alt="" decoding="async"><h3>${E(localize('job',j.id,'title',j.title))}</h3><dl><div><dt>${V('income')}</dt><dd class="v14-compare-income">${j.min}–${j.max}<small>${V('month')}</small></dd></div><div><dt>${V('location')}</dt><dd>${E(j.park)} · ${E(j.location)}</dd></div><div><dt>${V('benefits')}</dt><dd>${tags(j,5)}</dd></div><div><dt>${V('cv')}</dt><dd>${V(j.type==='internal'?'needCv':'noCv')}</dd></div></dl><a class="btn red" href="${jobHref(j)}">${V('details')}${I('arrow','sm')}</a></article>`).join('')}</div><p class="v14-salary-disclaimer">${V('salaryNote')}</p></div>`;document.body.append(layer);window.MDTranslate?.apply(currentLang,layer);localizePageLinks(layer);focusDialog(layer);layer.addEventListener('click',e=>{if(e.target===layer||e.target.closest('.modal-close'))layer.remove();});protectImages(layer);applyImageTransforms();}
function updateNews(){const target=qs('#newsListing');if(!target)return;const term=normalizeSearch(newsQuery).trim();const posts=db.posts.filter(p=>p.visible&&(newsKind==='all'||p.type===newsKind)&&(!term||normalizeSearch([p.title,p.excerpt,p.category,localize('post',p.id,'title',p.title)].join(' ')).includes(term)));target.innerHTML=posts.map(p=>cardPost(p)).join('')||`<div class="md-empty"><h2>${V('noNews')}</h2><p>${V('noNewsDesc')}</p><button type="button" class="btn light" data-news-reset>${V('allContent')}</button></div>`;qsa('[data-news-kind]').forEach(b=>{b.setAttribute('aria-pressed',String(b.dataset.newsKind===newsKind));b.classList.toggle('active',b.dataset.newsKind===newsKind);});qs('#newsResultCount').textContent=posts.length+' · '+V(newsKind==='video'?'videos':newsKind==='article'?'articles':'allContent');const current=new URL(location.href);if(newsKind==='all')current.searchParams.delete('kind');else current.searchParams.set('kind',newsKind);if(newsQuery)current.searchParams.set('q',newsQuery);else current.searchParams.delete('q');current.searchParams.set('lang',currentLang);history.replaceState(history.state,'',current.pathname+current.search+current.hash);if(window.MDTranslate)window.MDTranslate.apply(currentLang,target);protectImages(target);localizePageLinks(target);applyImageTransforms();}
function protectCompanyLogo(img){let fallback;const failed=()=>{if(!img.isConnected)return;img.hidden=true;if(!fallback){fallback=document.createElement('span');fallback.className='partner-mark-text partner-logo-fallback';fallback.textContent=img.dataset.logoName||img.alt||'Logo';img.after(fallback);}};const loaded=()=>{img.hidden=false;fallback?.remove();fallback=null;};img.addEventListener('error',failed);img.addEventListener('load',loaded);if(img.complete&&img.getAttribute('src')){if(img.naturalWidth)loaded();else failed();}}
function protectImages(root=document){root.querySelectorAll('img').forEach(img=>{if(img.dataset.imageGuard)return;img.dataset.imageGuard='1';if(img.closest('.partner-marquee-item,.partner-directory-mark,.partner-company-logo,.partner-logo-preview')){protectCompanyLogo(img);return;}let originalLink=null,placeholder=null;const fallback=()=>{if(!img.isConnected||img.closest('.v14-image-unavailable'))return;img.dataset.failedSrc=img.getAttribute('src')||'';if(img.parentElement?.tagName==='A'){originalLink=img.parentElement;placeholder=document.createElement('div');placeholder.className=originalLink.className;placeholder.style.cssText=originalLink.style.cssText;placeholder.append(...originalLink.childNodes);originalLink.replaceWith(placeholder);}const box=document.createElement('div');box.className='v14-image-unavailable';box.innerHTML=`${I('image')}<span>${V('imageFallback')}</span><button type="button" data-retry-image>${V('imageRetry')}</button>`;img.after(box);box.prepend(img);img.hidden=true;box.querySelector('button').addEventListener('click',retry);function retry(){img.hidden=false;const src=img.dataset.failedSrc;box.replaceWith(img);img.removeAttribute('src');img.src=src;}};img.addEventListener('error',fallback);img.addEventListener('load',()=>{img.classList.add('v14-image-ready');if(originalLink&&placeholder?.isConnected){originalLink.append(...placeholder.childNodes);placeholder.replaceWith(originalLink);originalLink=null;placeholder=null;}});if(img.complete&&!img.naturalWidth&&img.getAttribute('src'))fallback();});}
