  const service=e.target.closest('[data-service]');if(service){activeService=service.dataset.service;const serviceUrl=new URL(location.href);serviceUrl.searchParams.set('service',activeService);serviceUrl.searchParams.set('lang',currentLang);history.replaceState(null,'',serviceUrl.pathname+serviceUrl.search+serviceUrl.hash);const value=window.MD14.services.find(s=>s.id===activeService);qsa('[data-service]').forEach(t=>{const selected=t===service;t.setAttribute('aria-selected',String(selected));t.tabIndex=selected?0:-1;});qs('#service-panel').outerHTML=servicePanel(value);const dock=qs('.mobile-action-dock');if(dock)dock.outerHTML=mobileActionDock();return;}
  const remove=e.target.closest('[data-remove-filter]');if(remove){const key=remove.dataset.removeFilter;if(key==='saved')qs('#onlySaved').checked=false;else qs('#jobFilter').elements.namedItem(key).value='';filterPage=1;updateList();qs('#resultHeading').focus({preventScroll:true});return;}
  const kind=e.target.closest('[data-news-kind]');if(kind){newsKind=kind.dataset.newsKind;updateNews();return;}
