  if(e.target.closest('#contactNext')){const form=qs('#contactForm'),message=form.elements.message;const valid=message.value.trim().length>=10;qs('#contactStepError').hidden=valid;message.setAttribute('aria-invalid',String(!valid));if(!valid){message.setAttribute('aria-describedby','contactStepError');message.focus();return;}message.removeAttribute('aria-describedby');qs('[data-contact-step="1"]').hidden=true;qs('[data-contact-step="2"]').hidden=false;qs('[data-contact-progress="1"]').classList.remove('is-current');qs('[data-contact-progress="2"]').classList.add('is-current');qs('#contactReview').textContent=message.value.trim();qs('#contactName').focus();return;}
  if(e.target.closest('#contactBack')){qs('[data-contact-step="1"]').hidden=false;qs('[data-contact-step="2"]').hidden=true;qs('[data-contact-progress="2"]').classList.remove('is-current');qs('[data-contact-progress="1"]').classList.add('is-current');qs('#briefMessage').focus();return;}
